    <div class="entry-header">
        <h5>Reference @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Name" @oninput="e => { Name = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Relationship" @oninput="e => { Relationship = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @oninput="e => { Email = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @oninput="e => { Phone = e.Value?.ToString() ?? ""; NotifyChanged(); }" class="form-control" />
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Name, string Relationship, string Email, string Phone)> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Name, Relationship, Email, Phone));
    }
}

@namespace sv_f24e2938439846c89d570b32c95fd881.Components.Pages.Apply

<div class="step-form references-step">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var idx = i;
        var reference = References[idx];
        <ReferenceForm
            Index="idx"
            Name="@reference.Name"
            Relationship="@reference.Relationship"
            Email="@reference.Email"
            Phone="@reference.Phone"
            ShowRemove="@(References.Count > 1)"
            OnRemove="() => RemoveReference(idx)"
            OnChanged="HandleReferenceChanged" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            StateHasChanged();
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 1)
        {
            References.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void HandleReferenceChanged((int Index, string Name, string Relationship, string Email, string Phone) data)
    {
        if (data.Index < References.Count)
        {
            var r = References[data.Index];
            r.Name = data.Name;
            r.Relationship = data.Relationship;
            r.Email = data.Email;
            r.Phone = data.Phone;
        }
    }

    private async Task HandleNext()
    {
        ValidationError = null;
        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ValidationError = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

@namespace sv_f24e2938439846c89d570b32c95fd881.Components.Pages.Apply

<div class="step-form cover-letter-step">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea"
                  @bind="CoverLetterText" @bind:event="oninput"
                  maxlength="@MaxLength" rows="12"></textarea>
        <div class="char-count">@CoverLetterText.Length / @MaxLength characters</div>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-buttons">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;
        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ValidationError = "Please write a cover letter.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetterText);
    }
}

@namespace sv_f24e2938439846c89d570b32c95fd881.Components.Pages.Apply
@using sv_f24e2938439846c89d570b32c95fd881.Models

<div class="step-form review-step">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will review your application and get back to you.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-section-header">
                <h4>Personal Information</h4>
                <button class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>Work History</h4>
                <button class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>References</h4>
                <button class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    @r.Email &bull; @r.Phone
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-section-header">
                <h4>Cover Letter</h4>
                <button class="btn btn-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="validation-error">@SubmitError</div>
        }

        <div class="step-buttons">
            <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? SubmitError;

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;
        IsSubmitting = true;
        SubmitError = null;
        StateHasChanged();

        try
        {
            ApplicationId = await OnSubmit();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            SubmitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

