+    background: #0d6efd;
+    color: white;
+}
+
+.step.completed .step-circle {
+    border-color: #198754;
+    background: #198754;
+    color: white;
+}
+
+.step.dimmed .step-circle {
+    border-color: #dee2e6;
+    background: #f8f9fa;
+    color: #adb5bd;
+}
+
+.step-label {
+    margin-top: 0.5rem;
+    font-size: 0.75rem;
+    text-align: center;
+    color: #666;
+}
+
+.step.active .step-label {
+    color: #0d6efd;
+    font-weight: 600;
+}
+
+.step.completed .step-label {
+    color: #198754;
+}
+
+.step.dimmed .step-label {
+    color: #adb5bd;
+}
+
+.step-connector {
+    flex: 1;
+    height: 2px;
+    background: #dee2e6;
+    margin: 0 0.5rem;
+    margin-bottom: 1.5rem;
+}
+
+.step-connector.completed {
+    background: #198754;
+}
+
+/* Form Styles */
+.step-form {
+    background: white;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    padding: 2rem;
+}
+
+.form-group {
+    margin-bottom: 1rem;
+}
+
+.form-group label {
+    display: block;
+    margin-bottom: 0.25rem;
+    font-weight: 500;
+    font-size: 0.9rem;
+}
+
+.form-control {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #ced4da;
+    border-radius: 4px;
+    font-size: 1rem;
+    box-sizing: border-box;
+}
+
+.form-control:focus {
+    border-color: #86b7fe;
+    outline: 0;
+    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
+}
+
+.form-row {
+    display: flex;
+    gap: 1rem;
+}
+
+.form-row .form-group {
+    flex: 1;
+}
+
+.form-check {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+.form-check input[type="checkbox"] {
+    width: auto;
+}
+
+/* Buttons */
+.step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+.btn {
+    padding: 0.5rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    border: none;
+    text-decoration: none;
+}
+
+.btn:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-primary {
+    background: #0d6efd;
+    color: white;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-outline {
+    background: white;
+    border: 1px solid #6c757d;
+    color: #6c757d;
+}
+
+.btn-outline:hover {
+    background: #f8f9fa;
+}
+
+.btn-secondary {
+    background: #6c757d;
+    color: white;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #5c636a;
+}
+
+.btn-danger {
+    background: #dc3545;
+    color: white;
+}
+
+.btn-sm {
+    padding: 0.25rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+.btn-link {
+    background: none;
+    color: #0d6efd;
+    padding: 0;
+    text-decoration: underline;
+    cursor: pointer;
+    border: none;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1.1rem;
+}
+
+/* Validation */
+.validation-error {
+    color: #dc3545;
+    background: #f8d7da;
+    padding: 0.75rem;
+    border-radius: 4px;
+    margin-top: 1rem;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #dc3545;
+    font-size: 0.8rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+/* Work Entry / Reference Forms */
+.work-entry-form,
+.reference-form {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.entry-header h5 {
+    margin: 0;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 250px;
+    resize: vertical;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.8rem;
+    color: #6c757d;
+    margin-top: 0.25rem;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e9ecef;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h4 {
+    margin: 0;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #555;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+}
+
+.submission-confirmation h4 {
+    color: #198754;
+    font-size: 1.5rem;
+    margin-bottom: 1rem;
+}
+
+.step-description {
+    color: #6c757d;
+    margin-bottom: 1rem;
+}
+

